            "cluster-g-z": "Mamu-G*009:01_nov",
            "cluster-b16": "Mamu-B16*001:01_nov",
            "cluster-a1": "Mamu-A1*001:01_nov",
            "cluster-i": "Mamu-I*001:01_nov",
