        controller.configure(result: makeCandidateResult(
            bundleURL: bundleURL,
            calls: [
                makeCall(
                    sample: "AnimalA",
                    genotype: "known-control",
                    reads: 9
                ),
            ],
            candidates: [
                makeCandidate(
                    id: "search-candidate",
                    name: provisionalName,
                    classification: .novel,
                    support: .singleton,
                    samples: ["AnimalA"]
                ),
            ],
            observations: [
                makeCandidateObservation(
