        let calls = (0..<12).flatMap { row -> [ONTGenotypeCall] in
            sampleIDs.enumerated().map { sample, sampleID in
                makeCall(
                    sample: sampleID,
                    genotype: String(format: "%02d_Mafa_A1", row),
                    reads: row + sample + 1
                )
            }
        }
