            calls: [call],
            stats: ONTGenotypeRunStats(
                totalInputReads: 10,
                retainedUniqueReads: 5
            )
        )
        let updated = makeResult(
            bundleURL: bundleURL,
            samples: [],
            calls: [call],
            haplotypeAnalysis: makeEmptyHaplotypeAnalysis(),
            stats: ONTGenotypeRunStats(
